import { IngestPipeline } from "@514labs/moose-lib";

export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number;
}

// Create the ingestion pipeline with ClickHouse table optimized for our query patterns:
// 1. Activity counts per user over a date range -> order by userId, eventTs
// 2. Total duration per action type -> action should be early in ordering
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["userId", "eventTs", "action"]
  },
  stream: true,
  ingestApi: true,
});

