const fs = require('fs');

// Read and parse CSV data
const csvData = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf8');
const lines = csvData.trim().split('\n');
const headers = lines[0].split(',');

// Convert CSV to JSON records
const records = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',');
  if (values.length === headers.length) {
    const record = {
      eventId: values[0],
      eventTs: new Date(values[1]).toISOString(),
      userId: values[2],
      action: values[3],
      durationMs: parseFloat(values[4]) || 0 // Default null/NaN to 0
    };
    records.push(record);
  }
}

console.log(`Converted ${records.length} records`);

// Load data through Moose ingestion API
async function loadData() {
  for (const record of records) {
    try {
      const response = await fetch('http://localhost:4000/ingest/UserActivity', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(record)
      });

      if (!response.ok) {
        console.error(`Failed to load record ${record.eventId}:`, await response.text());
      } else {
        console.log(`✓ Loaded ${record.eventId}`);
      }
    } catch (error) {
      console.error(`Error loading record ${record.eventId}:`, error.message);
    }
  }
  console.log('Data loading complete!');
}

loadData();

